def main():
    print(f"UHS Topics Count: {len(UHS_TOPICS)}")
    print(f"PLAB Topics Count: {len(PLAB_TOPICS)}")
    print(f"AMC Topics Count: {len(AMC_TOPICS)}")

    assert len(UHS_TOPICS) == 100, f"Expected 100 UHS topics, got {len(UHS_TOPICS)}"
    assert len(PLAB_TOPICS) == 100, f"Expected 100 PLAB topics, got {len(PLAB_TOPICS)}"
    assert len(AMC_TOPICS) == 100, f"Expected 100 AMC topics, got {len(AMC_TOPICS)}"

    for name, lst in [("UHS", UHS_TOPICS), ("PLAB", PLAB_TOPICS), ("AMC", AMC_TOPICS)]:
        for i, t in enumerate(lst):
            assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at {name} #{i}: {t[0]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at {name} #{i}: {t[0]}"
            assert t[5].startswith("https://"), f"Invalid URL at {name} #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega97_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 97A topics (UHS 100, PLAB 100, AMC 100)\n\n")
        f.write(f"UHS_TOPICS = {json.dumps(UHS_TOPICS, indent=2)}\n\n")
        f.write(f"PLAB_TOPICS = {json.dumps(PLAB_TOPICS, indent=2)}\n\n")
        f.write(f"AMC_TOPICS = {json.dumps(AMC_TOPICS, indent=2)}\n")

    print(f"Saved Mega-Batch 97A topics to {out_path}!")

if __name__ == "__main__":
    main()
